-- ====================================================================================================== BotConfig line
local function findModule(name)
	for _, d in game:GetDescendants() do
		if d:IsA("ModuleScript") and d.Name == name and not d:FindFirstAncestorWhichIsA("Model") then
			local ok, path = pcall(function() return d:GetFullName() end)
			if ok and not path:find("_Backup") and not path:find("_Orig") then return d end
		end
	end
end
local BOT_ADD = ', "House/CollisionProxies"'
local function botConfig(add)
	local bc = findModule("BotConfig")
	if not bc then return "no BotConfig" end
	local src = bc.Source
	local has = src:find(BOT_ADD, 1, true) ~= nil
	if add and not has then
		local a, b = src:find("CoverFolders%s*=%s*{[^}]*")
		if not a then return "BotConfig: no CoverFolders line" end
		local head = src:sub(1, b):gsub("%s+$", "")
		bc.Source = head .. BOT_ADD .. " " .. src:sub(b + 1):gsub("^%s+", "")
		return "BotConfig += House"
	elseif not add and has then
		bc.Source = src:gsub(BOT_ADD:gsub("%p", "%%%0") .. " ?", "", 1)
		return "BotConfig -= House"
	end
	return "BotConfig ="
end

