		local bk = SS:FindFirstChild("_House_Backup") or Instance.new("Folder")
		bk.Name = "_House_Backup"; bk.Parent = SS
		m.Name = m.Name .. "_" .. os.time(); m.Parent = bk
	elseif m then
		m:Destroy()
	end
end
